        EXPECT_EQ(printed.find("Cached models"), std::string::npos);
        EXPECT_EQ(printed.find("pipe-failed"), std::string::npos);

        const EngineMiniXashStartup* record = EngineMini_XashStartup();
        ASSERT_NE(record->spr_load, nullptr);
