        EXPECT_EQ(g_EngineMiniSprLoad, &SPR_Load);
        EXPECT_EQ(record->spr_load_calls, 0);
        expect_prior(record);
        EXPECT_EQ(engine->SPR_Shutdown.GetHook(), nullptr);
