        EXPECT_EQ(sensitivity.flags, goldsrc::FCVAR_ARCHIVE);
        EXPECT_FLOAT_EQ(sensitivity.value, 3.0f);
        EXPECT_STREQ(sensitivity.string, "3.0");
        EXPECT_STREQ(sensitivity.name, "sensitivity");
