            EXPECT_EQ(record->spr_width_calls, 0);
            EXPECT_EQ(record->spr_set, &SPR_Set);
            EXPECT_EQ(g_EngineMiniSprSet, &SPR_Set);
            EXPECT_EQ(record->spr_set_calls, 0);
            EXPECT_EQ(record->spr_disable_scissor, &SPR_DisableScissor);
