            EXPECT_EQ(ghCrosshair, 9);
            EXPECT_EQ(gCrosshairRc.left, 1);
            EXPECT_EQ(gCrosshairRc.top, 2);
            EXPECT_EQ(gCrosshairRc.right, 13);
            EXPECT_EQ(gCrosshairRc.bottom, 14);
            EXPECT_EQ(gCrosshairR, 21);
