            EXPECT_EQ(mod_known_info[0].firstCRCDone, 1);
            EXPECT_EQ(mod_known_info[0].initialCRC, 0xC5C5C5C5u);
            EXPECT_EQ(mod_known_info[1].shouldCRC, 0);
            EXPECT_EQ(mod_known_info[1].firstCRCDone, 0);
