        for (int i = 0; i < 256; ++i)
        {
            texgammatable[i] = static_cast<uint8_t>((i * 7 + 13) & 0xFF);
        }
        for (int i = 0; i < 1024; ++i)
        {
            lightgammatable[i] = (i * 11 + 17) & 0x3FF;
            lineargammatable[i] = (i * 13 + 19) & 0x3FF;
            screengammatable[i] = (i * 15 + 23) & 0x3FF;
        }
        auto expect_gamma_tables = [&]() {
            for (int i = 0; i < 256; ++i)
            {
                EXPECT_EQ(texgammatable[i], static_cast<uint8_t>((i * 7 + 13) & 0xFF)) << i;
            }
            for (int i = 0; i < 1024; ++i)
            {
                EXPECT_EQ(lightgammatable[i], (i * 11 + 17) & 0x3FF) << i;
                EXPECT_EQ(lineargammatable[i], (i * 13 + 19) & 0x3FF) << i;
                EXPECT_EQ(screengammatable[i], (i * 15 + 23) & 0x3FF) << i;
            }
        };

